import { pack } from "./pack.mjs";

const HIST = ["history", "satoshi-nakamoto", "whitepaper"];
const NODE = ["nodes", "consensus", "governance"];
const WAL = ["self-custody", "derivation_path", "public_key_vs_private_key"];
const MON = ["scarce", "money", "mining"];
const ECO = ["austrian_school_of_economics", "problems-of-money", "money"];

export const PART_G = [].concat(
    pack("app", [
        ["app-favor-exact", "What is Satoshi's Favor?", "Satoshi's Favor is the community mining game in Quest Hub. You contribute points, then hash during a window for a chance at the prize. Open Quest Hub, then Favor, or open the miner. This describes a Bitcoin Quest feature, not financial advice.", ["favor", "quest-hub"], "features.registry.js entry favor."],
        ["app-xp-earn", "How do I earn XP on Bitcoin Quest?", "XP is how you rank up on Bitcoin Quest. Daily XP is full through 500, half through 900, then a quarter until 1,000, and each tier rounds down. You earn points by reading, quests, chat, and badges. This describes a Bitcoin Quest feature, not financial advice.", ["xp", "one-stop-shop"], "features.registry.js entry xp."],
        ["app-raffle-here", "How do raffles work here?", "The raffle takes Orange Ticket entries bought in the Nook. A winner is drawn on the 1st. More entries improve the odds, and this is a game inside the app. This describes a Bitcoin Quest feature, not financial advice.", ["raffle", "nook", "tickets"], "features.registry.js entry raffle."],
        ["app-questhub-exact", "What is the Quest Hub?", "Quest Hub holds the daily quiz, trivia, poll, Flex, Favor, raid, charity, the community challenge, and the Nook. Open it from the menu and pick a tab along the top. This describes a Bitcoin Quest feature, not financial advice.", ["quest-hub", "one-stop-shop"], "features.registry.js entry quest-hub."],
        ["app-2fa-on", "How do I turn on two-factor auth?", "Open Settings, then Security, and turn on 2FA with an authenticator app or the phone option. The Security page also covers your password, linked accounts, blocking, and account deletion. This describes a Bitcoin Quest feature, not financial advice.", ["security", "settings"], "features.registry.js entry security."],
        ["app-orange-what", "What are Orange Tickets?", "Orange Tickets are the shop currency in Bitcoin Quest. You earn them from the daily spin, activity, and referrals, and you spend them in the Nook. Your balance is under Settings, then Account. This describes a Bitcoin Quest feature, not financial advice.", ["tickets", "nook"], "features.registry.js entry tickets."],
        ["app-quiz-what", "What is the daily quiz?", "The daily quiz is a Quest Hub tab with one scored run a day. Open Quest Hub and choose the Quiz tab. The server checks the reward. This describes a Bitcoin Quest feature, not financial advice.", ["qh-quiz", "quest-hub"], "features.registry.js entry qh-quiz."],
        ["app-gifts-exact", "How do gifts work in the app?", "Gifts come from the daily spin wheel. You open them for keys, locked ciphers, tickets, XP, or a rare prize, on the post-spin screen or from Settings, then Account, then Peers. This describes a Bitcoin Quest feature, not financial advice.", ["gifts", "wheel"], "features.registry.js entry gifts."],
        ["app-powalk", "What is Proof of Walk?", "Proof of Walk connects Strava so a walk can earn XP. Open Proof of Walk and connect Strava, and if the feature is paused the page says so. This describes a Bitcoin Quest feature, not financial advice.", ["proof-of-walk", "health"], "features.registry.js entry proof-of-walk."],
        ["app-ln-withdraw", "How do Lightning withdrawals work here?", "Lightning withdrawals pay a saved Lightning address that looks like an email, and the address is treated as permanent unless support changes it. The lifetime cap is 15,000 sats per user. The Lightning page can also connect with WebLN or NWC. This describes an app rule, not income and not financial advice.", ["sats", "ln-address", "lightning-wallet"], "ranking.js lifetime line and lightning.js connect options, as of 2026."],
        ["app-xp-cap", "What is the daily XP cap?", "The daily XP cap on Bitcoin Quest is 1,000. Gains are full through 500, half through 900, then a quarter until 1,000, and extra XP is not saved. The Today card shows the day's progress. This describes a Bitcoin Quest feature, not financial advice.", ["xp", "one-stop-shop"], "features.registry.js entry xp."],
        ["app-nook-exact", "What is Nacho's Nook?", "Nacho's Nook is the shop inside Quest Hub where you spend Orange Tickets. Open Quest Hub, then the Nook, to buy items such as raffle entries. Inventory is the side that holds what you own. This describes a Bitcoin Quest feature, not financial advice.", ["nook", "tickets"], "features.registry.js entry nook."],
        ["app-cipher-what", "What is a locked cipher in the app?", "A locked cipher opens when you use a key that has the same label. If an accepted peer sent the key and you open the cipher, you both get the same prize and they see a reveal of what you won. That counts as one of their 21 cipher opens that day, pays once per cipher, and includes sats only when both accounts are eligible. Ask in Chat whether anyone has the key. Open Quest Hub, then Nook or Inventory, pick the cipher, and use a matching key. This describes a Bitcoin Quest feature, not financial advice.", ["ciphers", "keys"], "features.registry.js entry ciphers."],
        ["app-keys-exact", "How do cipher keys work here?", "Cipher keys open locked ciphers when the label matches. You can send up to 3 keys to each accepted peer per day. If an accepted peer opens a matching cipher with a key you sent, you both get the same prize and you see a reveal of what you won. That counts as one of your 21 cipher opens that day, pays once per cipher, and includes sats only when both accounts are eligible. Keys live in Inventory. This describes a Bitcoin Quest feature, not financial advice.", ["keys", "peers"], "features.registry.js entry keys."],
        ["app-spin-what", "What is the daily spin?", "The daily spin wheel gives one free spin for tickets, XP, or a gift. Open it from the home row and take today's spin. A gift you land can be opened next. This describes a Bitcoin Quest feature, not financial advice.", ["wheel", "gifts"], "features.registry.js entry wheel."],
        ["app-tctv-what", "What is Timechain TV on this site?", "Timechain TV plays Bitcoin videos around the clock. Watching 10 minutes in a day can earn 100 XP and 1 orange ticket. Open Timechain TV and pick a channel. This describes a Bitcoin Quest feature, not financial advice.", ["tv", "tctv-watch"], "features.registry.js entries tv and tctv-watch."],
        ["app-badges-exact", "What are badges in the app?", "Badges mark things you have done, from chat to quests to hidden goals. Open the leaderboard to see progress. This describes a Bitcoin Quest feature, not financial advice.", ["badges", "leaderboard"], "features.registry.js entry badges."],
        ["app-pleb-what", "What is PlebTalk?", "PlebTalk is the forum, and articles are the long-form tab inside it. A new top-level post can show up in Global Chat. Open PlebTalk to read or start a discussion. This describes a Bitcoin Quest feature, not financial advice.", ["forum", "global-chat"], "features.registry.js entry forum."]
    ]),
    pack("basics", [
        ["basics-adam", "Who is Adam Back?", "Adam Back invented Hashcash in 1997, the proof-of-work design the Bitcoin whitepaper cites. He is a cryptographer, and no public proof shows he is Satoshi. Hashcash showed that a stamp could cost computation.", HIST, "Hashcash, 1997, cited by the whitepaper."],
        ["basics-szabo", "Who is Nick Szabo?", "Nick Szabo described Bit Gold, an earlier design for scarce digital money that used proof of work. Bitcoin is not Bit Gold, and his authorship of Bitcoin is not proven. The design is part of the prehistory.", ["history", "satoshi-nakamoto"], "Bit Gold, pre-Bitcoin."],
        ["basics-wei", "Who is Wei Dai?", "Wei Dai proposed b-money in 1998 as money among people who do not trust each other. The Bitcoin whitepaper cites that work. Dai is not a proven identity for Satoshi.", HIST, "b-money, 1998."],
        ["basics-wuille", "Who is Pieter Wuille?", "Pieter Wuille is a Bitcoin developer associated with hierarchical wallets, SegWit, and later Schnorr and Taproot work, among other contributions. He does not own the protocol. Code still has to be run by nodes.", ["developers", "history", "taproot"], "Public developer history."],
        ["basics-maxwell", "Who is Gregory Maxwell?", "Gregory Maxwell is a long-time Bitcoin developer who worked on privacy ideas and consensus research. He does not set the rules alone. Nodes still choose what software to run.", ["developers", "history"], "Public developer history."],
        ["basics-left", "When did Satoshi stop posting in public?", "Satoshi's last widely cited public forum posts are from December 2010. A note to a developer in April 2011 said he had moved on to other things. The network has kept producing blocks without that account.", ["satoshi-nakamoto", "history"], "Forum record and the April 2011 note."],
        ["basics-mtgox", "What happened to Mt Gox?", "Mt Gox was a large early exchange that halted withdrawals and entered bankruptcy proceedings in February 2014 after saying customer bitcoin was missing. The exact missing amount was disputed for years, so it is not frozen here. The lesson is that an exchange balance is a claim on a company.", ["history", "self-custody", "risks__threats__attack_vectors__weaknes"], "February 2014 bankruptcy. Amount omitted as disputed."],
        ["basics-core-name", "Why is the main software called Bitcoin Core?", "The main software was long called Bitcoin-Qt and is now Bitcoin Core. The name change did not create a company that owns the chain. Other programs can implement the same consensus rules.", ["core-source-code", "history"], "Project rename. Not ownership."],
        ["basics-forum", "Where did early bitcoin discussion happen?", "Early public discussion happened on the BitcoinTalk forum and on mailing lists, not inside the blocks. Those archives are history, and they are not a governance council. Anyone can still propose an idea in public.", ["history", "governance"], "BitcoinTalk and mailing lists."],
        ["basics-list", "Where was the whitepaper announced?", "The Bitcoin whitepaper was announced on a cryptography mailing list on 31 October 2008. That list was a discussion place, not a company. The paper itself is the design document.", ["whitepaper", "history"], "31 October 2008 mailing-list post."],
        ["basics-first-release", "When was the first Bitcoin software released?", "Satoshi released the first Bitcoin software in January 2009, around the genesis block. Early versions were the client the network ran. Modern Bitcoin Core descends from that public code.", ["history", "core-source-code"], "January 2009 release."],
        ["basics-block170", "Why do people mention block 170?", "Block 170, on 12 January 2009, contains the first known transfer from Satoshi to Hal Finney, of 10 bitcoin. It is a normal transaction, not an admin function. Finney died in 2014.", ["history", "satoshi-nakamoto"], "Block 170, 12 January 2009."],
        ["basics-pseudo", "Why did the creator use a pseudonym?", "The creator used the name Satoshi Nakamoto and did not provide a verified legal identity. The protocol does not need that identity to keep running. Guesses about the person are not consensus rules.", ["satoshi-nakamoto", "history"], "Pseudonym. Identity unproven."],
        ["basics-foundation", "Does a foundation control Bitcoin?", "A group called the Bitcoin Foundation was formed in 2012 and does not own the protocol. A foundation can fund work and still cannot force nodes to change rules. There is no admin key in the software.", ["governance", "decentralized", "history"], "Bitcoin Foundation, 2012. Not consensus control."],
        ["basics-license", "What license is Bitcoin Core under?", "Bitcoin Core is published under the MIT license, which lets people use, change, and share the code. The license is not control over other people's nodes. Consensus is what running software enforces.", ["open_source", "core-source-code"], "MIT license of Bitcoin Core."],
        ["basics-cpp", "What language is Bitcoin Core written in?", "Bitcoin Core is written mainly in C++. Other teams have written nodes in other languages. The language does not set the rules, and the rules are what running nodes check.", ["core-source-code", "developers"], "Bitcoin Core source language."],
        ["basics-port", "What network port do Bitcoin nodes use?", "Bitcoin nodes typically accept mainnet peer connections on port 8333. That is a network default, not a secret. A node can be configured otherwise.", ["nodes", "core-source-code"], "Default mainnet port 8333."],
        ["basics-sat-name", "Why is the small unit called a satoshi?", "The smallest unit is called a satoshi, after the creator's pseudonym. One bitcoin is 100 million of them. The name is a wallet and culture convention, and the protocol counts integer units.", ["sats__or__bits", "money", "satoshi-nakamoto"], "Unit name. 100 million per bitcoin."]
    ]),
    pack("monetary", [
        ["money-subsidy-epoch", "What is a subsidy epoch?", "A subsidy epoch is a span of 210,000 blocks that share the same new-coin reward. The reward starts at 50 bitcoin and halves each epoch. The epoch is counted in blocks, not on a government calendar.", MON, "210,000-block epochs."],
        ["money-span", "Why does the subsidy change every 210000 blocks?", "The software divides issuance into 210,000-block spans, about four years if blocks average ten minutes. That spacing is a choice in the code. Nodes enforce it, so a miner cannot shorten it alone.", ["scarce", "mining"], "Issuance span."],
        ["money-tiny", "When does the new-coin subsidy become tiny?", "After many halvings the new-coin reward becomes a tiny fraction of a bitcoin and then zero in the integer unit. Fees are the remaining payment to miners. The calendar year depends on real block times, so it is not a dated promise.", ["scarce", "tail_emission", "transaction_fees"], "Halving schedule. No calendar promise."],
        ["money-split", "Why can one bitcoin be split so far?", "Each bitcoin is divisible into 100 million units in the protocol. Splitting the unit does not create more bitcoin. It only lets people price smaller amounts.", ["money", "scarce", "sats__or__bits"], "100 million base units."],
        ["money-overflow", "What was the 2010 value overflow?", "In August 2010 a bug allowed a transaction to create outputs far beyond the intended supply, and upgraded nodes rejected that chain. The bad history was replaced by a valid chain. The incident shows why the client people run matters.", ["history", "scarce", "risks__threats__attack_vectors__weaknes"], "August 2010 value overflow."],
        ["money-lost-cap", "Do lost coins still count toward the cap?", "Coins with lost keys still count toward the 21 million cap, because the protocol cannot tell a lost key from a quiet holder. They simply are not spent. The spendable amount can be smaller than the cap without a rule change.", ["scarce", "money"], "Lost keys remain in the cap."],
        ["money-speed", "Who can speed up bitcoin issuance?", "No miner, exchange, or developer can speed the issuance schedule unless nodes accept different software. A block that pays the wrong subsidy is invalid. The schedule is checked, not set by the exchange price.", ["scarce", "consensus", "governance"], "Subsidy is validated."],
        ["money-estimate", "Why is a halving date only an estimate?", "A halving happens at a block height, and the calendar day assumes blocks average ten minutes. Real blocks are sometimes faster or slower until difficulty retargets. Treat a printed date as an estimate.", ["scarce", "block_time-block-size"], "Height, not a civil date."],
        ["money-labels", "Why do wallets show different unit names?", "Wallets may label amounts as BTC, sats, or bits. Those are display choices over the same integer units. The chain does not store the label.", ["sats__or__bits", "money"], "Display units."],
        ["money-sats-habit", "Why do many people count in sats?", "Counting in sats avoids decimals and matches the integer the protocol uses. One sat is the smallest unit. The habit is practical, and it is not a second coin.", ["sats__or__bits", "money"], "Integer units."],
        ["money-stock", "What is the stock of bitcoin?", "The stock is the coins that already exist. New subsidy adds to that stock on a schedule. Lost keys do not delete those coins from the historical cap.", ["scarce", "money"], "Existing coins."],
        ["money-flow", "What is the flow of new bitcoin?", "The flow is the new coins a valid block may create. Halvings cut that flow. Flow is not the exchange price.", ["scarce", "mining"], "New issuance."],
        ["money-audit", "How can a person audit issuance?", "A full node adds up the subsidy rules and rejects a block that mints too much. You do not need an exchange report for that check. The audit is validation itself.", ["nodes", "scarce"], "Full-node validation."]
    ]),
    pack("mining", [
        ["mining-double-sha", "Why does mining hash the header twice?", "Mining hashes the block header with SHA-256 and then SHA-256 again. That double hash is the proof-of-work input. A valid header has to land under the target.", ["mining", "0_mining__hashing"], "SHA-256d of the header."],
        ["mining-extranonce", "What is the extra nonce?", "The 4-byte nonce can run out, so miners also change an extra nonce in the coinbase, which changes the Merkle root and the header. That extends the search. It is still brute-force hashing, not a puzzle with a known shortcut.", ["mining", "0_mining__hashing"], "Coinbase extra nonce."],
        ["mining-header-fields", "What fields sit in a block header?", "A block header holds a version, the previous block hash, a Merkle root, a time, the compact target, and a nonce. Those fields are what gets hashed. The transactions sit under the Merkle root.", ["mining", "blockchain-timechain"], "Six header fields."],
        ["mining-header-size", "How big is a Bitcoin block header?", "A Bitcoin block header is 80 bytes. Mining searches for a header whose hash is low enough. The header stays small even when the block of transactions is large.", ["mining", "block_time-block-size"], "80-byte header."],
        ["mining-nbits", "What is nBits?", "nBits is the compact form of the mining target stored in the header. It encodes how small the hash must be. Difficulty is a human way to talk about that same target.", ["difficulty-adjustment", "mining"], "Compact target."],
        ["mining-2016", "Why retarget every 2016 blocks?", "Difficulty retargets every 2,016 blocks so the average stays near ten minutes. If the last span was fast, the target gets harder, and if it was slow, easier. One span cannot multiply or divide the difficulty by more than four.", ["difficulty-adjustment", "mining"], "2,016-block retarget, factor-of-four cap."],
        ["mining-two-weeks", "Why aim for two weeks between retargets?", "Two weeks is the design goal because 2,016 blocks at ten minutes is about that long. It is long enough to measure hashrate and short enough to react. It is not a promise that every span lasts exactly fourteen days.", ["difficulty-adjustment", "block_time-block-size"], "Design interval."],
        ["mining-time-rules", "What limits a block timestamp?", "A block time has to be later than the median of the previous eleven blocks. Nodes also reject a timestamp more than about two hours ahead of their own clock. Those rules stop a miner from dating blocks wildly.", ["time", "consensus", "mining"], "Median-time-past and future limit."],
        ["mining-maturity", "Why is coinbase maturity 100 blocks?", "The subsidy and fees in a coinbase cannot be spent until 100 blocks later. That delay gives a short reorg time to fall away. It is a consensus rule, not a pool policy.", ["mining", "consensus"], "100-block maturity."],
        ["mining-empty", "Can a block contain no user payments?", "A block can contain only the coinbase and still be valid if the header meets the target. Miners sometimes publish those while transactions are still arriving. User payments then wait for a later block.", ["mining", "transaction_fees"], "Empty blocks are valid."],
        ["mining-asicboost", "What is ASICBoost?", "ASICBoost is a way some mining hardware can try more header candidates with less work by using details of the header. It does not change the proof-of-work check nodes perform. Whether a miner uses it is a hardware and policy choice.", ["mining", "hardware"], "Header-grinding optimization. Not a rule change."],
        ["mining-payout", "What is a pool payout method?", "Methods such as pay per share or pay per last N shares are contracts with a pool, not consensus rules. The chain only sees the coinbase the pool broadcasts. Read the pool's own terms before joining.", ["mining", "governance"], "Pool contracts, not consensus."],
        ["mining-bitaxe", "What is a Bitaxe?", "A Bitaxe is a small open-source miner that hobbyists use to learn solo mining. It does not meaningfully change the odds against large machines. It is hardware, not a protocol role.", ["hardware", "mining", "projects-diy"], "Open-source hobby miner."]
    ]),
    pack("nodes", [
        ["nodes-bip9-def", "What is BIP9?", "BIP9 is a method for miners to signal readiness for a soft fork using version bits, measured over retarget periods. It was used around the CSV and SegWit deployments. Signaling is not the same as a node choosing the rules.", NODE, "BIP9 version bits."],
        ["nodes-bip8", "What is BIP8?", "BIP8 is a proposed way to deploy a soft fork with a block-height deadline. It is a process document, not an active consensus rule by itself. Taproot used a different signaling design.", ["governance", "consensus"], "BIP8 proposal."],
        ["nodes-bip16", "What is BIP16?", "BIP16 defines pay to script hash, so an address can commit to a script that is revealed when spending. It activated in 2012. The revealed script still has to pass the consensus checks.", ["consensus", "utxos"], "BIP16, activated 2012."],
        ["nodes-bip65", "What is BIP65?", "BIP65 added OP_CHECKLOCKTIMEVERIFY so a spend can require a block height or time to have passed. It activated in 2015. It is an absolute lock, not a relative one.", ["consensus", "smart-contracts"], "BIP65, activated 2015."],
        ["nodes-bip68", "What is BIP68?", "BIP68 lets an input encode a relative lock based on how old that input is. It activated with the CSV soft fork in 2016. Wallets use it for delays such as Lightning penalty paths.", ["consensus", "layer-2-lightning"], "BIP68, activated 2016."],
        ["nodes-bip112", "What is BIP112?", "BIP112 added OP_CHECKSEQUENCEVERIFY so a script can require the relative lock from BIP68. It activated in 2016 with the CSV soft fork. The script, not only the input field, can demand the delay.", ["consensus", "op-codes"], "BIP112, activated 2016."],
        ["nodes-bip141", "What is BIP141?", "BIP141 is the SegWit consensus change that moved signatures into a witness and fixed a third-party malleability problem. It activated in August 2017. Block capacity is measured in weight after it.", ["consensus", "block_time-block-size"], "BIP141, August 2017."],
        ["nodes-bip173", "What is BIP173?", "BIP173 defines bech32 addresses for native SegWit outputs. It is an address format, not a separate coin. A bech32 string is not a private key.", ["cryptography", "blockchain-timechain"], "BIP173 bech32."],
        ["nodes-bip125", "What is BIP125?", "BIP125 describes a policy for replacing an unconfirmed transaction when it signals that replacement is allowed. It is relay policy, which nodes can differ on, not a way to reverse a confirmed payment. The replacement still needs a fee the policy accepts.", ["rbf", "transaction_fees"], "BIP125 opt-in replacement policy."],
        ["nodes-bip174", "What does BIP174 define?", "BIP174 defines partially signed Bitcoin transactions, a format for passing a spend between wallets and devices. It is a coordination format, not a new signature algorithm. The chain only sees the final transaction.", ["self-custody", "developers"], "BIP174 PSBT."],
        ["nodes-bip340", "What is BIP340?", "BIP340 specifies Schnorr signatures on Bitcoin's curve. Taproot uses them. They are a signature scheme, not a new coin.", ["taproot", "cryptography"], "BIP340 Schnorr."],
        ["nodes-bip341", "What is BIP341?", "BIP341 defines Taproot outputs, which can spend with a key or with a revealed script. It activated in November 2021. Complex scripts can stay hidden when the key path is used.", ["taproot", "consensus"], "BIP341, November 2021."],
        ["nodes-bip342", "What is BIP342?", "BIP342 defines Tapscript, the script rules used in a Taproot script-path spend. It activated with Taproot in November 2021. It changes opcode and signature checks inside those scripts.", ["taproot", "op-codes"], "BIP342 Tapscript."],
        ["nodes-bip352", "What is BIP352?", "BIP352 describes silent payments, where a receiver publishes a static code and each payment can still create a fresh on-chain output. Wallet support was still spreading as of 2026. It does not hide amounts.", ["privacy-nonkyc", "cryptography"], "BIP352. Support noted as of 2026."],
        ["nodes-bip324", "What is BIP324?", "BIP324 specifies encrypted transport between nodes, sometimes called v2 transport. It protects the connection from casual observers on the wire. It does not make on-chain amounts private, and a live count of upgraded nodes is omitted.", ["nodes", "privacy-nonkyc"], "BIP324 transport. Not amount privacy."],
        ["nodes-bip119", "What is BIP119?", "BIP119 proposes OP_CHECKTEMPLATEVERIFY, also called CTV. CTV is a proposal and has not activated, so it is not a consensus rule as of 2026. Under a soft fork, nodes that have not upgraded still accept a CTV spend as a valid anyone-can-spend-style NOP, and only upgraded nodes enforce the new rule.", ["bip119", "ctv-covenants"], "BIP119 proposal, not activated as of 2026."],
        ["nodes-port-test", "What port does testnet use?", "The public test network traditionally uses port 18333, separate from mainnet port 8333. Test coins have no value on mainnet. Do not send real bitcoin to a test address.", ["nodes", "core-source-code"], "Testnet port 18333."],
        ["nodes-dns-use", "What is a DNS seed used for?", "A DNS seed returns addresses of nodes that a new node can try to reach. It is a bootstrap hint, not a source of truth about blocks. After connecting, the node checks headers and blocks itself.", ["nodes", "consensus"], "Bootstrap only."]
    ]),
    pack("cryptography", [
        ["crypto-checksig", "What does OP_CHECKSIG do?", "OP_CHECKSIG checks that a signature matches a public key and the transaction under the chosen sighash. It is how a standard single-key output is spent. A failed check makes the script fail.", ["op-codes", "cryptography"], "Opcode OP_CHECKSIG."],
        ["crypto-cltv", "What does OP_CHECKLOCKTIMEVERIFY do?", "OP_CHECKLOCKTIMEVERIFY fails the script if the transaction lock time has not reached the required height or time. It was added by BIP65. It cannot move coins by itself.", ["op-codes", "smart-contracts"], "BIP65 opcode."],
        ["crypto-csv-op", "What does OP_CHECKSEQUENCEVERIFY do?", "OP_CHECKSEQUENCEVERIFY fails the script unless the input is old enough under BIP68. It was added by BIP112. Lightning-style penalty transactions rely on this kind of delay.", ["op-codes", "layer-2-lightning"], "BIP112 opcode."],
        ["crypto-return", "What does OP_RETURN do?", "OP_RETURN marks an output as unspendable and can carry a small data payload. How much data nodes will relay is a policy choice and has changed, so a byte cap is not frozen here. It does not create a spendable coin.", ["op-codes", "utxos"], "Unspendable data output. Policy size omitted."],
        ["crypto-dup", "What does OP_DUP do?", "OP_DUP copies the top stack item. Older address scripts use it so a public key can be checked and then hashed. It is a stack operation, not a signature.", ["op-codes", "cryptography"], "Stack duplicate."],
        ["crypto-op-hash160", "What does OP_HASH160 do?", "OP_HASH160 hashes the top stack item with SHA-256 and then RIPEMD-160. Pay-to-public-key-hash scripts compare that 20-byte result. The hash is not the private key.", ["op-codes", "cryptography"], "SHA-256 then RIPEMD-160."],
        ["crypto-cat", "Why is OP_CAT disabled?", "OP_CAT would concatenate two stack items. It was disabled early because of script-risk concerns, and turning it back on is a soft-fork debate, not an active rule as of 2026. Do not assume a wallet can use it today.", ["op-codes", "consensus"], "Disabled. Not active as of 2026."],
        ["crypto-loops", "Why does Bitcoin Script avoid loops?", "Bitcoin Script has no loops, so a node can always finish checking a script. The limit keeps validation cheap and predictable. General programs are not an unbounded script on the base chain.", ["op-codes", "smart-contracts"], "No loops by design."],
        ["crypto-520", "What is the script stack element limit?", "A single stack element in a Bitcoin script cannot be larger than 520 bytes under consensus. That bound keeps validation finite. A script that breaks it is invalid.", ["op-codes", "consensus"], "520-byte stack element."],
        ["crypto-sighash-all", "What is SIGHASH_ALL?", "SIGHASH_ALL commits a signature to every input and every output of the transaction. Changing an output afterward invalidates that signature. It is the usual choice for a normal payment.", ["cryptography", "utxos"], "Default sighash."],
        ["crypto-anyonecanpay", "What is SIGHASH_ANYONECANPAY?", "SIGHASH_ANYONECANPAY lets a signature cover its own input so other inputs can be added later. It shows up in some coinjoin and crowdfunding constructions. Which outputs it commits to still depends on the other sighash flags.", ["cryptography", "coin_mixing_coinjoin_coin_control_utxo"], "Input-only commitment flag."],
        ["crypto-keypath", "What is a Taproot key-path spend?", "A key-path Taproot spend looks like a single signature on the output key. The script tree is not revealed. It is usually smaller when the signers agree.", ["taproot", "cryptography"], "BIP341 key path."],
        ["crypto-scriptpath", "What is a Taproot script-path spend?", "A script-path spend reveals the script being used and a proof that it was in the committed tree. Other hidden scripts stay unrevealed. It enforces more complex rules when the key path is not used.", ["taproot", "smart-contracts"], "BIP341 script path."],
        ["crypto-xonly", "What is an x-only public key?", "Schnorr public keys in Taproot store the 32-byte x coordinate, and the even y is implied. That is shorter than an older compressed key. It is still a public key, not a private key.", ["taproot", "public_key_vs_private_key"], "BIP340 x-only keys."],
        ["crypto-tagged", "What is a tagged hash?", "BIP340 uses tagged hashes so a hash for signatures is not confused with a hash for another job. The tag is part of the hash input. It separates domains, and it is not a new coin.", ["cryptography", "taproot"], "BIP340 tagged hashes."],
        ["crypto-older-hash", "Why do older addresses use a shorter hash?", "Older addresses commit to SHA-256 followed by RIPEMD-160, which is 20 bytes. The shorter hash made early addresses smaller. Taproot outputs commit to a 32-byte key instead.", ["cryptography", "blockchain-timechain"], "HASH160 versus 32-byte keys."]
    ]),
    pack("wallets", [
        ["wallets-no-photo", "Why is a photo of a seed a bad backup?", "A photo often lands in a camera roll that syncs to a cloud account. Whoever later opens that account can copy the words and move the coins. Paper or metal kept offline avoids that copy.", WAL, "Cloud-synced photos.", ["Is it safe to photograph my seed?", "Should I photograph my seed phrase?", "Is a photo a safe seed backup?"]],
        ["wallets-2of3", "How does a 2 of 3 savings setup work?", "A 2 of 3 setup needs any two of three keys to spend, so one lost key does not trap the coins and one stolen key is not enough. Each key should live in a different place. It is still your policy to design, and this is not legal advice.", ["self-custody", "public_key_vs_private_key"], "Threshold multisig. Not legal advice."],
        ["wallets-psbt-flow", "How does a PSBT move between devices?", "One device builds a partially signed transaction and passes that file to a signer, often by SD card, QR, or a cable. The signer adds a signature without exposing the seed. The finished transaction is what gets broadcast.", ["self-custody", "hardware"], "BIP174 flow."],
        ["wallets-desc-why", "Why do output descriptors matter?", "A descriptor is a compact recipe for the addresses a wallet will create, including the script type and the path. Backing up the descriptor plus the seed restores modern wallets more reliably than the seed alone in some setups. It does not replace keeping the seed offline.", ["derivation_path", "self-custody"], "Output descriptors."],
        ["wallets-offline", "What is offline signing?", "Offline signing builds the transaction on an online machine and signs it on a machine that does not need the network. The seed stays on the offline side. Only the signed transaction crosses back.", ["self-custody", "hardware"], "Air-gapped signing."],
        ["wallets-copies", "How should seed copies be separated?", "Keep more than one copy if losing a single page would ruin you, and keep those copies in different places. Do not leave a copy with someone who could use it alone unless that is the plan. This is practical storage, not legal advice.", ["self-custody"], "Separated backups. Not legal advice."],
        ["wallets-heir-lock", "How can a timelock help an heir?", "A script can require a long delay before an heir key works, while your own key works immediately. If you are still around, you move the coins before the delay. The exact script needs a careful wallet, and this is not legal or tax advice.", ["self-custody", "smart-contracts"], "Relative or absolute timelock. Not legal advice."],
        ["wallets-duress", "What is a duress PIN on a signer?", "Some hardware signers offer a second PIN that opens a decoy wallet or wipes the device. That is a product feature, not a Bitcoin consensus rule. Read that device's own guide before relying on it.", ["hardware", "self-custody"], "Product feature, not consensus."],
        ["wallets-spend-policy", "What is a spending policy?", "A spending policy is the set of keys, delays, and conditions that must be met before coins move. Miniscript is one way to write those conditions in a structured form. The chain enforces the script, not a written wish.", ["self-custody", "op-codes"], "Script policy."],
        ["wallets-receive-check", "What should you read before a large receive?", "Confirm the address on the device that holds the keys, not only on a computer screen that could be swapped. A small test payment is a common habit for a new destination. The habit does not make an exchange into self-custody.", ["self-custody", "hardware"], "On-device check."]
    ]),
    pack("layers", [
        ["layers-bolt", "What is a BOLT?", "BOLT means Basis of Lightning Technology, the set of documents that describe how Lightning implementations talk. They are specifications for the layer, not Bitcoin consensus. Implementations can lag or differ.", ["layer-2-lightning", "lightning_node"], "Lightning specification set."],
        ["layers-bolt11", "What is a BOLT11 invoice?", "A BOLT11 invoice is a one-time Lightning payment request with an amount, an expiry, and a payment hash. Payment succeeds when the preimage matches that hash. It is not a reusable offer. It is not an on-chain address, and it is not a private key.", ["layer-2-lightning"], "BOLT11 is one-time, not a reusable offer."],
        ["layers-expire", "Why do Lightning invoices expire?", "An invoice commits to a payment hash and a route that may not stay liquid. Expiry stops a stale request from being paid into a channel that changed. Create a new invoice if the old one lapses.", ["layer-2-lightning"], "Invoice expiry."],
        ["layers-size", "What limits the size of a Lightning payment?", "A payment cannot exceed the liquidity along a route, including channel reserves. Very large payments may need a bigger channel or an on-chain transaction. The limit is the path, not the 21 million cap.", ["layer-2-lightning", "lightning_node"], "Route liquidity."],
        ["layers-route-def", "What is Lightning routing?", "Routing is how a payment hops across channels from payer to receiver without every pair having a direct channel. Each hop learns only its neighbors, not the whole path, in the usual onion design. The hops charge a small fee set by their operators.", ["layer-2-lightning"], "Onion routing over channels.", ["Can a lightning node act as a router?", "Does a lightning node route payments?", "Can my node forward Lightning payments?"]],
        ["layers-cheat-penalty", "Why can a Lightning cheater lose funds?", "If a peer publishes an old channel state, the honest side can spend the cheater's output during a delay. That penalty is what makes publishing a stale state expensive. A watchtower or an online wallet has to notice in time.", ["layer-2-lightning", "lightning_node"], "Justice transaction."],
        ["layers-fed-trust", "What do you trust in a Fedimint?", "A Fedimint is a community mint whose guardians hold bitcoin and issue blinded ecash. You trust that a threshold of guardians stays honest and available. It is not the same as a key only you hold.", ["fedimints", "fedi-ark"], "Federated custody."],
        ["layers-cashu-trust", "What do you trust with Cashu?", "Cashu ecash is a note blinded so the mint should not see who paid whom, while the mint still holds the bitcoin. You trust that mint to redeem the note. Blind signatures do not remove the custodian.", ["chaumian-mints", "chaumian_e-cash_and_blind_signatures"], "Mint custody plus blinding."],
        ["layers-liquid-trust", "What do you trust on Liquid?", "Liquid is a federated sidechain: a set of functionaries controls the pegged bitcoin. You trust that federation to honor peg-outs. It can be useful and it is not base-layer self-custody.", ["sidechains", "layer-3-sidechains"], "Federated peg."],
        ["layers-ark-problem", "What problem is Ark trying to solve?", "Ark aims at sharing a pool of bitcoin so many people can receive payments without each opening a Lightning channel. It was still a young protocol as of 2026, with different trust details by design. It is not a second bitcoin.", ["fedi-ark", "layer-2-lightning"], "Ark, young as of 2026."],
        ["layers-state-trust", "What do you trust in a statechain?", "A statechain transfers the right to spend a UTXO by passing key material through a coordinator, often with a timeout back to the previous owner. You trust the coordinator not to collude against the current owner. It is a different trust model from a private key you never share.", ["sidechains", "self-custody"], "Coordinator trust."],
        ["layers-not-l1", "Why is a layer not the base chain?", "A layer can add speed or privacy by keeping some state off the global ledger. The bitcoin that backs it is only as safe as the exit back to a transaction nodes will accept. Calling a layer bitcoin does not give it the base chain's validation.", ["scalability", "layer-2-lightning"], "Exit to L1."]
    ]),
    pack("privacy", [
        ["privacy-bip78", "What is BIP78?", "BIP78 describes payjoin, a payment where the receiver adds an input so the transfer does not look like one person paying another. Both sides need wallet support. It is optional, and it does not hide the amounts.", ["coin_mixing_coinjoin_coin_control_utxo", "privacy-nonkyc"], "BIP78 payjoin."],
        ["privacy-vpn", "Does a VPN hide an on-chain payment?", "A VPN can hide your home IP from the node you connect to. It does not hide amounts, addresses, or links between inputs once a transaction is in a block. Network privacy and ledger privacy are different problems.", ["privacy-nonkyc", "nodes"], "IP versus ledger."],
        ["privacy-no-percent", "Why not quote a privacy score?", "A single percentage would pretend that chain analysis is a fixed science. Heuristics change, and a wallet's leaks depend on how you use it. This archive describes tools and limits instead of a score.", ["privacy-nonkyc", "coin_mixing_coinjoin_coin_control_utxo"], "No invented percentage."],
        ["privacy-fresh", "Why create a fresh address per payment?", "Reusing an address links those payments for anyone reading the chain. A fresh address does not make you anonymous, and it removes that easy link. Many wallets do this unless you override them.", ["privacy-nonkyc", "blockchain-timechain"], "Address reuse."]
    ]),
    pack("fees", [
        ["fees-weight-vb", "How does block weight become vbytes?", "SegWit weight counts witness bytes less heavily than other bytes, and a vbyte is that weight divided by four. Fees are usually quoted in sats per vbyte. The division is a unit conversion, not a second fee market.", ["vbyte", "transaction_fees"], "Weight divided by four."],
        ["fees-miner-sees", "What fee rate does a miner actually see?", "A miner looking at a transaction sees the fee divided by the size it will take in the block, usually talked about as sats per vbyte. Ancestor transactions can lower the package rate. The number on a website is an estimate of that view.", ["transaction_fees", "vbyte"], "Fee per weight."],
        ["fees-change-cost", "Does sending change make a payment larger?", "Yes, an extra change output adds bytes, so the fee is higher than a payment that spends the inputs exactly. Wallets add change whenever the inputs overshoot. Coin selection is how they try to keep that cost reasonable.", ["transaction_fees", "utxos"], "Change output size."]
    ]),
    pack("economics", [
        ["econ-bretton", "What was the Bretton Woods system?", "Bretton Woods was the mid-century arrangement that pegged many currencies to the dollar and the dollar to gold for foreign governments. It is history, and it ended in practice when convertibility stopped. Bitcoin's supply rule is not a revival of that treaty.", ECO, "Mid-century peg. Not a bitcoin rule."],
        ["econ-gold-window", "Who ended dollar convertibility to gold?", "In August 1971 the United States stopped redeeming dollars for gold for foreign governments. That closed the gold window of the Bretton Woods era. Bitcoin did not exist yet, and people study the date as fiat history.", ["problems-of-money", "history"], "August 1971."],
        ["econ-fractional", "What is fractional reserve banking?", "A fractional-reserve bank keeps only part of deposits in cash and lends the rest. The practice lets the broader money supply expand beyond base money. It is a banking arrangement, not something Bitcoin nodes do.", ["problems-of-money", "money"], "Bank lending of deposits."],
        ["econ-bankrun", "What is a bank run?", "A bank run is when many depositors ask for cash at once and the bank cannot pay them all immediately. The mismatch comes from lending deposits out. Bitcoin in your own keys does not have that queue.", ["problems-of-money", "self-custody"], "Deposit mismatch."],
        ["econ-lolr", "What is a lender of last resort?", "A lender of last resort is a central bank that lends to banks during a run so they can pay depositors. That support can also expand the money supply. Bitcoin has no such office inside the protocol.", ["problems-of-money", "politics"], "Central-bank backstop."],
        ["econ-equation", "What is the equation of exchange?", "The equation of exchange says the money supply times how often it is spent relates to prices times output. It is an accounting identity, not a law that predicts the bitcoin exchange rate. This archive does not turn it into a forecast.", ["austrian_school_of_economics", "money"], "MV and PY. Not a forecast."],
        ["econ-yield-diff", "How is saving different from a yield product?", "Saving is holding money you did not spend. A yield product pays you by lending, by taking risk, or by diluting someone else. Bitcoin's protocol does not pay a yield for holding.", ["money", "investment-strategy"], "No protocol yield."],
        ["econ-credit", "Can credit exist around bitcoin?", "People can still lend bitcoin or borrow against it with contracts outside the base protocol. Those contracts add counterparty risk the chain does not erase. The 21 million cap does not ban credit.", ["money", "austrian_school_of_economics"], "Credit is outside consensus."],
        ["econ-quality", "Why can a price index miss quality changes?", "Economists debate how a price index treats goods that get better or worse. That method is called quality adjustment. A single percentage is not the whole of purchasing power.", ["problems-of-money", "money"], "Quality adjustments are debated."],
        ["econ-coincidence", "What is the double coincidence of wants?", "Barter needs each person to want what the other has, at the same time. Money removes that coincidence by being something almost anyone will accept next. Bitcoin is studied as a candidate for that role, not as a completed world price list.", ["money", "philosophy"], "Barter limit."],
        ["econ-indirect", "Why did people move to indirect exchange?", "Indirect exchange means selling your good for a widely accepted money, then buying what you want. It scales better than finding a perfect barter match. Which good becomes money is a market outcome, not a decree in the Bitcoin code.", ["money", "austrian_school_of_economics"], "Indirect exchange."],
        ["econ-stock-flow-diff", "How is a stock different from a flow?", "A stock is a pile measured at a moment, and a flow is a rate over time. Bitcoin's existing coins are the stock, and the subsidy is the flow. Mixing the two makes issuance debates muddy.", ["scarce", "money"], "Stock versus flow."]
    ]),
    pack("adoption", [
        ["adopt-etf-date", "When did United States spot bitcoin ETFs start?", "The US SEC approved spot bitcoin ETFs on January 10, 2024, and they began trading on January 11, 2024. A share is a claim on a fund, not a key in your wallet. Live holdings change, so this note does not freeze a total.", ["news-adoption", "regulation", "investment-strategy"], "Approved January 10, 2024. Trading began January 11, 2024."],
        ["adopt-sv-date", "When did El Salvador make bitcoin legal tender?", "El Salvador made bitcoin legal tender in 2021. Later politics changed parts of that policy, and this note does not freeze a later statute. The protocol did not change either way.", ["news-adoption", "geopolitics___macroeconomics", "regulation"], "2021 legal tender. Later statutes not frozen."],
        ["adopt-treasury-start", "When did public companies start bitcoin treasuries?", "Some public companies began holding bitcoin in treasury, and MicroStrategy's purchases starting in 2020 are a widely cited example. A company balance is not the protocol supply, and live totals go stale. This is not a suggestion to copy a company.", ["giga-chad", "news-adoption"], "From 2020. Live totals omitted."]
    ]),
    pack("regulation", [
        ["reg-no-rates", "Why does this archive skip tax rates?", "Tax rates, forms, and holding periods differ by country and change. A number copied here would become wrong and could be mistaken for advice. Keep your own records and ask a qualified person where you live.", ["regulation", "investment-strategy"], "Country-agnostic. Not tax advice."],
        ["reg-two-countries", "Why can two countries treat bitcoin differently?", "Each state writes its own tax, licensing, and payments rules. The Bitcoin network does not look up those statutes when it checks a signature. Legal treatment and consensus validity are separate questions, and this is not legal advice.", ["regulation", "politics"], "Local law versus consensus."]
    ]),
    pack("scams", [
        ["scams-remote", "Why is remote screen sharing dangerous around a wallet?", "A stranger who can see or drive your screen can change a destination or walk you into revealing a seed. Never install remote-control software for someone who offers to fix a wallet. Close the chat and use a channel you looked up yourself.", ["risks__threats__attack_vectors__weaknes", "self-custody"], "Remote-access scams."],
        ["scams-ads", "Why are wallet ads in search results risky?", "An ad can sit above the real site and lead to a lookalike that asks for a seed. Type an address you already trust, or use a bookmark. The first result is not a verification.", ["risks__threats__attack_vectors__weaknes", "self-custody"], "Search-ad lookalikes."],
        ["scams-device-check", "What should you check on the device before sending?", "Read the address and the amount on the signer itself, not only in the app that built the payment. A swapped screen on the computer is a known trick. If the device does not match, do not approve.", ["hardware", "self-custody"], "On-device confirmation."],
        ["scams-urgency", "Why do bitcoin scams rush you?", "Urgency stops you from checking a domain, a device, or a second channel. A real protocol does not expire your savings in the next ten minutes. Pause when a message demands speed.", ["risks__threats__attack_vectors__weaknes", "misconceptions-fud"], "Pressure tactic."]
    ]),
    pack("culture", [
        ["culture-orange-pill", "What does orange pilling mean?", "Orange pilling means helping someone understand Bitcoin, a play on a famous movie metaphor and on bitcoin's orange color. It is teaching, not a dare to speculate. People learn at different speeds.", ["orange-pilling", "memes-funny"], "Teaching slang."],
        ["culture-bitcoiner", "What does the word bitcoiner mean?", "A bitcoiner is someone who studies or uses Bitcoin, often in preference to other tokens. The word is culture, not a membership card. There is no office that issues the title.", ["memes-funny", "maximalism"], "Cultural label."],
        ["culture-running", "What does running bitcoin refer to?", "On 11 January 2009 Hal Finney posted that he was running bitcoin, an early public sign the software worked. People quote it as history. It is not a command you must type to hold coins.", ["history", "memes-funny", "satoshi-nakamoto"], "Hal Finney, 11 January 2009."],
        ["culture-honey-money", "Why call bitcoin the honey badger of money?", "The honey badger joke says bitcoin keeps going through bans, bugs, and headlines the way the animal is said to shrug off threats. It is a meme about resilience. It is not a zoology claim or a promise about the exchange rate.", ["memes-funny", "misconceptions-fud"], "Meme."],
        ["culture-fix-money", "What does fix the money mean here?", "Fix the money, fix the world is a slogan that sound money changes incentives. It is not a promise that software solves every social problem. Treat it as a prompt to study money.", ["memes-funny", "philosophy", "money"], "Slogan, not a forecast."],
        ["culture-vires", "What does vires in numeris mean?", "Vires in numeris is Latin used in bitcoin culture for strength in numbers. It points at verification by math instead of by a person's word. It is a motto, not a consensus rule.", ["memes-funny", "cryptography"], "Cultural motto."],
        ["culture-tick", "What does tick tock next block mean?", "Tick tock, next block is a shrug at waiting for the next confirmation instead of refreshing a price. Blocks arrive on their own schedule. The joke prefers the chain to the headline.", ["memes-funny", "blockchain-timechain"], "Meme."],
        ["culture-whitepaper-day", "When do people mark whitepaper day?", "People mark 31 October as the anniversary of the 2008 whitepaper. It is a culture date, like pizza day in May. The network does not treat that day differently.", ["whitepaper", "history", "memes-funny"], "31 October 2008."]
    ]),
    pack("fud", [
        ["fud-energy-per-tx", "Why is energy per transaction a weak comparison?", "Mining secures the stock of coins and the history, not only the payments in the latest block. Dividing a year's energy by one day's transfers ignores layers and batches. The ratio is a slogan unless the method is stated.", ["environment___energy", "energy", "misconceptions-fud"], "Stock of security versus one block."],
        ["fud-loops", "Is missing general computation a flaw?", "Bitcoin Script refuses loops so every node can finish validation. Other systems sell unbounded programs and then have to limit them anyway with fees and committees. The limit is a choice about who can check the chain.", ["op-codes", "misconceptions-fud", "smart-contracts"], "Validation bound."],
        ["fud-ten-min", "Is a ten minute block a failure?", "Ten minutes is the average target so blocks can propagate before the next one and so difficulty has a stable sample. It is slow for coffee and fine for final settlement. Lightning and other layers exist for faster payments.", ["block_time-block-size", "layer-2-lightning", "misconceptions-fud"], "Design interval."],
        ["fud-etf-rules", "Do ETF sponsors write the consensus rules?", "An ETF sponsor can buy and sell bitcoin through custodians and can shape a fund's paperwork. Sponsors do not get a vote that nodes must honor. A block is still valid or invalid under the software users run.", ["regulation", "governance", "misconceptions-fud"], "Funds are not miners of rules."],
        ["fud-old", "Is an old protocol automatically obsolete?", "Age means the rules have been attacked in public for a long time, which is the Lindy argument. New features still arrive by soft fork when users run them. Old is not the same as finished or as broken.", ["lindy_effect", "misconceptions-fud"], "Lindy versus stagnation."],
        ["fud-one-country", "Can one country delete the ledger?", "A country can pressure people and businesses inside its borders. Copies of the chain outside that reach keep the history. Deleting every copy is a different task from regulating an exchange.", ["decentralized", "regulation", "misconceptions-fud"], "Local pressure, global copies."],
        ["fud-slogan", "Is a bitcoin slogan a price forecast?", "Slogans such as number-go-up are jokes or hopes. The protocol does not promise a future exchange rate. A meme is not an analysis.", ["memes-funny", "misconceptions-fud", "market_cap"], "Memes are not forecasts."],
        ["fud-layer-trust", "Does using a layer abandon self-custody?", "It depends on the layer. A Lightning channel you can close to the chain is closer to self-custody than a federated mint you must trust to redeem. Read the exit path before calling the balance yours.", ["layer-2-lightning", "self-custody", "misconceptions-fud"], "Exit path decides."]
    ])
);
